// unary, called as by invokePlain
func r2(p *pegort.Parser) (*pegort.Node, bool) {
	if p.Control == nil {

		start, rec, trail := p.Pos, len(p.Recovered), len(p.Trail)
		prevEnv, prevCut := p.Env, p.Cut
		p.Cut = false
		p.Depth++
		if p.Depth > p.MaxDepth {
			p.TooDeep()
		}
		v, ok := e2(p)
		p.Depth--
		p.Cut = prevCut
		p.Trail = p.Trail[:trail]
		if ok {
			v = p.Finish(rules[2], pegort.EmptyFrame, v, start)
		} else {
			p.Pos = start
			p.Recovered = p.Recovered[:rec]
		}
		p.Env = prevEnv
		return v, ok
	}

	p.StepWork()
	start, rec, trail := p.Pos, len(p.Recovered), len(p.Trail)
	prevEnv, prevCut := p.Env, p.Cut
	p.Cut = false
	p.Depth++
	if p.Depth > p.MaxDepth {
		p.TooDeep()
	}
	v, ok := e2(p)
	p.Depth--
	p.Cut = prevCut
	p.Trail = p.Trail[:trail]
	if ok {
		v = p.Finish(rules[2], pegort.EmptyFrame, v, start)
	} else {
		p.Pos = start
		p.Recovered = p.Recovered[:rec]
	}
	p.Env = prevEnv
	return v, ok
}

